mapper.select:
SELECT sbdi.id, sbdi.code, sbdi.so_code, sbdi.so_delivery_code, sbdi.so_outstock_code, sbdid.sku_id, sbdid.sku_no, sbdid.delivery_qty, sbdid.warehouse_id, sbdid.warehouse_name, sbdi.logistics_channel_id, sbdi.logistics_channel_name, sbdi.bill_type, sbdi.transport_no, sbdi.cancel_status, sbdi.intercept_status, sbdi.handle_status, sbdi.handle_result, sbdi.remark, sbdi.create_user_name, sbdi.handle_user_name, sbdi.create_time, sbdi.handle_time FROM so_b2c_delivery_intercept_detail sbdid LEFT JOIN so_b2c_delivery_intercept sbdi ON sbdid.main_id = sbdi.id AND sbdid.is_deleted = FALSE WHERE sbdi.is_deleted = FALSE
AND sbdi.handle_status = #{params.tabFlag}
AND sbdi.code ILIKE concat('%',#{params.code}::text,'%')
AND sbdi.so_code ILIKE concat('%',#{params.soCode}::text,'%')
AND sbdi.so_delivery_code ILIKE concat('%',#{params.soDeliveryCode}::text,'%')
AND sbdi.so_outstock_code ILIKE concat('%',#{params.soOutstockCode}::text,'%')
AND sbdid.sku_no in
#{skuNo}
AND sbdi.logistics_channel_id in
#{logisticsChannelId}
AND sbdi.transport_no ILIKE concat('%',#{params.transportNo}::text,'%')
AND sbdi.cancel_status = #{params.cancelStatus}
AND sbdi.intercept_status = #{params.interceptStatus}
AND sbdi.handle_status = #{params.handleStatus}
AND sbdi.handle_result = #{params.handleResult}
AND sbdi.create_user_id in
#{createUserId}
AND sbdi.create_time >= #{params.createTimeList[0]} AND sbdi.create_time < (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' )
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sbdi.create_time desc
